<script setup>
import {ref,watch,inject,computed} from 'vue'
const props=defineProps({modelValue:Boolean,kind:String,definition:Object,domain:Object})
const emit=defineEmits(['update:modelValue','saved'])
const repo=inject('repository'),notify=inject('notify'),tab=ref('visual'),form=ref({}),error=ref(''),success=ref(''),saving=ref(false)
const risk=computed(()=>props.kind==='risk'),limit=computed(()=>props.domain?.config.limits[props.definition?.id])
const code=computed(()=>!props.definition?'':JSON.stringify({definition:props.definition,runtime:form.value},null,2)+'\n\n'+(risk.value?props.domain.workflows.code(props.definition.id):props.domain.metricCode()))
watch(()=>[props.modelValue,props.definition],()=>{if(props.modelValue&&props.definition){form.value=JSON.parse(JSON.stringify(props.domain.config.get(props.kind,props.definition.id)));tab.value='visual';error.value='';success.value=''}},{immediate:true})
watch(form,()=>success.value='',{deep:true})
async function save(){saving.value=true;error.value='';try{await repo.saveConfig(props.kind,props.definition.id,form.value);notify('运行参数已保存');emit('saved',props.definition.id);success.value='运行参数已保存，已应用到后续演示计算。'}catch(e){error.value=e.message}finally{saving.value=false}}
</script>
<template>
<VDialog :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)" max-width="980" scrollable><VCard v-if="definition" class="domain-dialog"><div class="dialog-heading"><div><span class="eyebrow">{{risk?'临床规则':'管理指标'}} · {{definition.id}}</span><h2>{{definition.name}}</h2></div><VBtn icon="tabler-x" variant="text" color="secondary" aria-label="关闭配置" @click="emit('update:modelValue',false)"/></div><VTabs v-model="tab" color="primary"><VTab value="visual">可视化查看</VTab><VTab value="code">代码查看</VTab></VTabs><VDivider/><VCardText>
<template v-if="tab==='visual'">
<p class="muted mb-5">{{definition.desc}} {{definition.advice}}</p>
<div v-if="risk" class="workflow-grid"><div v-for="(step,i) in [{title:'触发时机',text:definition.workflow.trigger},{title:'判断依据',text:definition.workflow.standard},{title:'什么是异常',text:definition.threshold},{title:'告警去向',text:form.recipients?.join('、')}]" :key="step.title" class="workflow-step"><span class="step-number">{{i+1}}</span><h3>{{step.title}}</h3><p>{{step.text}}</p></div></div>
<template v-else><div class="workflow-grid metric-flow"><div class="workflow-step"><span class="eyebrow">输入</span><h3>来源系统</h3><p v-for="s in definition.dataSources" :key="s.field">{{s.source}} · {{s.field}}</p></div><div class="workflow-step"><span class="eyebrow">固定规则</span><h3>计算公式</h3><p>{{definition.formula.display}}</p></div><div class="workflow-step"><span class="eyebrow">输出</span><h3>{{definition.name}}</h3><p>单位 {{definition.unit}} · 统计维度 {{definition.dimension}}</p></div></div></template>
<VAlert v-if="risk" :type="definition.workflow.supported?'info':'warning'" variant="tonal" class="my-5"><strong>{{definition.workflow.supported?'必要字段已具备':'数据源不支持'}}</strong><div>{{definition.workflow.sourceNote}}</div><div class="mt-2">所需字段：{{definition.workflow.fields.join('、')}}</div></VAlert>
<p v-if="risk" class="caption muted my-4">{{({event:'一次业务判断',deadline:'截止时点判断',stream:'连续窗口判断'})[definition.workflow.mode]}} · 同一业务事件与规则只产生一条告警。</p>
<VExpansionPanels v-else variant="accordion" class="my-5"><VExpansionPanel title="公式变量与数据来源"><VExpansionPanelText><VTable><thead><tr><th>变量</th><th>解释</th><th>来源</th></tr></thead><tbody><tr v-for="v in definition.formula.vars" :key="v.name"><td>{{v.name}}</td><td>{{v.desc}}</td><td>{{v.source}}</td></tr></tbody></VTable><VDivider/><VTable><thead><tr><th>字段</th><th>类型</th><th>系统 / 集合</th></tr></thead><tbody><tr v-for="s in definition.dataSources" :key="s.field"><td>{{s.field}}</td><td>{{s.typeLabel||s.type}}</td><td>{{s.source}} / {{s.collection}}</td></tr></tbody></VTable></VExpansionPanelText></VExpansionPanel></VExpansionPanels>
<h3 class="subheading mb-4">运行参数</h3><div class="form-grid">
<template v-if="risk"><VSwitch v-model="form.enabled" label="启用自动判断" :disabled="!definition.workflow.supported" color="primary" hide-details class="mb-4"/><div class="field full-width"><label>告警接收角色（至少一项）</label><VSelect v-model="form.recipients" :items="domain.workflows.roles" multiple chips closable-chips aria-label="告警接收角色"/></div><div v-if="limit" class="field"><label>{{limit.label}}</label><VTextField v-model.number="form.threshold" type="number" :min="limit.min" :max="limit.max" :step="definition.id==='INTRA-08'?0.1:1" :hint="`允许范围 ${limit.min}–${limit.max}`" persistent-hint/></div></template>
<template v-else><div class="field"><label>指标分类</label><VSelect v-model="form.category" :items="Object.entries(domain.categories).map(([value,title])=>({value,title}))"/></div><div class="field"><label>前端刷新频次（分钟）</label><VTextField v-model.number="form.frequency" type="number" min="1" max="1440" hint="仅刷新演示计算，不代表后台采集频次" persistent-hint/></div><div v-for="(t,i) in definition.thresholds" :key="i" class="field"><label>{{t.label}} · {{t.direction==='below'?'≤':'≥'}} · {{t.unit}}</label><VTextField v-model.number="form.thresholds[i]" type="number" min="0" :max="t.unit==='%'?100:undefined" step="any" :hint="t.desc" persistent-hint/></div></template></div>
</template><template v-else><VAlert type="info" variant="tonal" class="mb-4">发布定义和检测代码只读；运行参数在可视化页修改。</VAlert><pre class="json-view">{{code}}</pre></template>
<VAlert v-if="success" type="success" variant="tonal" class="mt-4" role="status">{{success}}</VAlert><VAlert v-if="error" type="error" variant="tonal" class="mt-4" role="alert">{{error}}</VAlert>
</VCardText><VDivider/><VCardActions><span class="caption muted">{{risk?'缺失来源不会被当作患者异常。':'确定性模拟指标，不代表正式国考统计口径。'}}</span><VSpacer/><VBtn variant="text" color="secondary" @click="emit('update:modelValue',false)">{{success?'关闭':'取消'}}</VBtn><VBtn variant="flat" :loading="saving" @click="save">保存运行参数</VBtn></VCardActions></VCard></VDialog>
</template>
